bruteForceSolution.code:
function reverseArray(nums) {
  let temp = [];
  for (let i = nums.length - 1; i >= 0; i--) {
    temp.push(nums[i]);
  }
  for (let i = 0; i < nums.length; i++) {
    nums[i] = temp[i];
  }
  return nums;
}

